1	package darksafe
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"math"
9		"regexp"
10		"sort"
11		"strconv"
12		"strings"
13	)
14	
15	// Point 是一条序列上某个时间戳的采样值。
16	type Point struct {
17		Timestamp int64   `json:"timestamp"`
18		Value     float64 `json:"value"`
19	}
20	
21	// SeriesView 是结果输出用的一条序列视图，标签按键升序呈现。
22	type SeriesView struct {
23		Name   string            `json:"name"`
24		Labels map[string]string `json:"labels"`
25		Points []Point           `json:"points"`
26	}
27	
28	// QuerySeries 是查询结果中的一条序列：完整身份与区间内点的个数及算术平均值。
29	type QuerySeries struct {
30		Name    string            `json:"name"`
31		Labels  map[string]string `json:"labels"`
32		Count   int               `json:"count"`
33		Average float64           `json:"average"`
34	}
35	
36	// QueryResult 是一次区间均值查询成功后的结果，只读，不改变存储。
37	type QueryResult struct {
38		Status string        `json:"status"`
39		Op     string        `json:"op"`
40		Series []QuerySeries `json:"series"`
41	}
42	
43	// BatchResult 是一批采样点写入成功后的结果。
44	type BatchResult struct {
45		Status     string       `json:"status"`
46		Added      int          `json:"added"`
47		Duplicates int          `json:"duplicates"`
48		Series     []SeriesView `json:"series"`
49	}
50	
51	// SeriesRef 标识一条序列：指标名加完整标签集合。
52	// 缺少某个标签与该标签值为空字符串属于不同序列。
53	type SeriesRef struct {
54		Name   string            `json:"name"`
55		Labels map[string]string `json:"labels"`
56	}
57	
58	// Conflict 描述同一序列同一时间戳已存在不同的值。
59	type Conflict struct {
60		Series    SeriesRef `json:"series"`
61		Timestamp int64     `json:"timestamp"`
62		Existing  float64   `json:"existing"`
63		Submitted float64   `json:"submitted"`
64	}
65	
66	// LineError 是一行（一批）输入失败后的结构化结果。
67	// Line 由命令入口按从 1 开始的行号填入；Index 为采样点在批次内从 1 开始的位置，
68	// 整行 JSON 无法解析或不是数组时 Index 为零并省略。
69	type LineError struct {
70		Status   string    `json:"status"`
71		Line     int       `json:"line,omitempty"`
72		Index    int       `json:"index,omitempty"`
73		Error    string    `json:"error"`
74		Conflict *Conflict `json:"conflict,omitempty"`
75	}
76	
77	// MetricStore 保存一次命令运行期间已写入的指标数据，仅存在于内存中，进程结束即丢弃。
78	type MetricStore struct {
79		series map[seriesID]*storedSeries
80	}
81	
82	// seriesID 是序列的规范身份，标签书写顺序不影响身份。
83	type seriesID struct {
84		name string
85		// sig 为排序后标签键值对的长度前缀拼接，避免不同写法产生碰撞。
86		sig string
87	}
88	
89	type storedSeries struct {
90		ref    SeriesRef
91		points map[int64]float64
92	}
93	
94	// NewMetricStore 创建一个空的指标存储。
95	func NewMetricStore() *MetricStore {
96		return &MetricStore{series: make(map[seriesID]*storedSeries)}
97	}
98	
99	func sortedKeys(m map[string]string) []string {
100		keys := make([]string, 0, len(m))
101		for k := range m {
102			keys = append(keys, k)
103		}
104		sort.Strings(keys)
105		return keys
106	}
107	
108	func makeSeriesID(name string, labels map[string]string) seriesID {
109		var b strings.Builder
110		for _, k := range sortedKeys(labels) {
111			v := labels[k]
112			fmt.Fprintf(&b, "%d:%s;%d:%s;", len(k), k, len(v), v)
113		}
114		return seriesID{name: name, sig: b.String()}
115	}
116	
117	// labelPair 是标签键值对字典序比较的单元。
118	type labelPair struct {
119		Key, Value string
120	}
121	
122	func sortedPairs(labels map[string]string) []labelPair {
123		keys := sortedKeys(labels)
124		pairs := make([]labelPair, len(keys))
125		for i, k := range keys {
126			pairs[i] = labelPair{Key: k, Value: labels[k]}
127		}
128		return pairs
129	}
130	
131	func compareLabelPairs(a, b []labelPair) int {
132		n := len(a)
133		if len(b) < n {
134			n = len(b)
135		}
136		for i := 0; i < n; i++ {
137			if a[i].Key != b[i].Key {
138				return strings.Compare(a[i].Key, b[i].Key)
139			}
140			if a[i].Value != b[i].Value {
141				return strings.Compare(a[i].Value, b[i].Value)
142			}
143		}
144		switch {
145		case len(a) < len(b):
146			return -1
147		case len(a) > len(b):
148			return 1
149		}
150		return 0
151	}
152	
153	var (
154		jsonIntegerRE = regexp.MustCompile(`^-?(0|[1-9][0-9]*)$`)
155		jsonNumberRE  = regexp.MustCompile(`^-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?$`)
156	)
157	
158	// ProcessLine 处理一行非空输入：JSON 数组为写入批次，JSON 对象为查询/操作。
159	// 成功时返回 BatchResult 或 *QueryResult；失败返回 *LineError（Index 始终为零）。
160	func (s *MetricStore) ProcessLine(line string) (any, *LineError) {
161		top, ok, lerr := decodeTopValue(line)
162		if lerr != nil {
163			return nil, lerr
164		}
165		switch ok {
166		case '[':
167			var items []json.RawMessage
168			if err := json.Unmarshal(top, &items); err != nil {
169				return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
170			}
171			return s.ingestItems(items)
172		case '{':
173			return s.queryFromObject(top)
174		default:
175			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples or a query object"}
176		}
177	}
178	
179	// IngestLine 解析并写入一行（一批）采样点。成功返回 BatchResult；
180	// 失败返回 *LineError，此时此前各批数据保留、本批不写入任何数据。
181	func (s *MetricStore) IngestLine(line string) (*BatchResult, *LineError) {
182		top, ok, lerr := decodeTopValue(line)
183		if lerr != nil {
184			return nil, lerr
185		}
186		if ok != '[' {
187			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples"}
188		}
189		var items []json.RawMessage
190		if err := json.Unmarshal(top, &items); err != nil {
191			return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
192		}
193		return s.ingestItems(items)
194	}
195	
196	// QueryLine 解析并执行一行查询对象。成功返回 QueryResult；查询只读，不改变存储。
197	func (s *MetricStore) QueryLine(line string) (*QueryResult, *LineError) {
198		top, ok, lerr := decodeTopValue(line)
199		if lerr != nil {
200			return nil, lerr
201		}
202		if ok != '{' {
203			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a query object"}
204		}
205		return s.queryFromObject(top)
206	}
207	
208	// decodeTopValue 解析单行中唯一的 JSON 值并返回其原始内容与首个非空白字节
209	// （'[' 或 '{'）。整个值无法解析、为空或存在尾随内容时返回 *LineError。
210	func decodeTopValue(line string) (json.RawMessage, byte, *LineError) {
211		dec := json.NewDecoder(strings.NewReader(line))
212		var top json.RawMessage
213		if err := dec.Decode(&top); err != nil {
214			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
215		}
216		// 第一个 JSON 值之后只允许输入结束（Decoder 自动跳过尾随空白）。
217		if err := dec.Decode(new(json.RawMessage)); err != io.EOF {
218			if err == nil {
219				err = fmt.Errorf("unexpected content after the JSON value")
220			}
221			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
222		}
223		trimmed := strings.TrimSpace(string(top))
224		if len(trimmed) == 0 || (trimmed[0] != '[' && trimmed[0] != '{') {
225			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples or a query object"}
226		}
227		return top, trimmed[0], nil
228	}
229	
230	type parsedSample struct {
231		name   string
232		ts     int64
233		value  float64
234		labels map[string]string
235	}
236	
237	// parseSample 对单个采样点做严格校验：仅允许四个已知字段、拒绝重复键，
238	// 标量必须是精确的 JSON 类型，timestamp 为 int64 整数，value 为有限 float64。
239	func parseSample(raw json.RawMessage) (parsedSample, error) {
240		var p parsedSample
241		p.labels = map[string]string{}
242		dec := json.NewDecoder(bytes.NewReader(raw))
243		dec.UseNumber()
244	
245		tok, err := dec.Token()
246		if err != nil {
247			return p, err
248		}
249		if d, ok := tok.(json.Delim); !ok || d != '{' {
250			return p, fmt.Errorf("each sample must be a JSON object")
251		}
252	
253		present := make(map[string]bool)
254		for dec.More() {
255			keyTok, err := dec.Token()
256			if err != nil {
257				return p, err
258			}
259			key := keyTok.(string)
260			switch key {
261			case "name", "timestamp", "value", "labels":
262			default:
263				return p, fmt.Errorf("unknown field %q", key)
264			}
265			if present[key] {
266				return p, fmt.Errorf("duplicate field %q", key)
267			}
268			present[key] = true
269	
270			switch key {
271			case "name":
272				t, err := dec.Token()
273				if err != nil {
274					return p, err
275				}
276				s, ok := t.(string)
277				if !ok {
278					return p, fmt.Errorf(`field "name" must be a string`)
279				}
280				if s == "" {
281					return p, fmt.Errorf(`field "name" must be a non-empty string`)
282				}
283				p.name = s
284			case "timestamp":
285				n, err := nextJSONNumber(dec, "timestamp")
286				if err != nil {
287					return p, err
288				}
289				v, err := parseJSONInt(n)
290				if err != nil {
291					return p, fmt.Errorf(`field "timestamp": %s`, err)
292				}
293				p.ts = v
294			case "value":
295				n, err := nextJSONNumber(dec, "value")
296				if err != nil {
297					return p, err
298				}
299				v, err := parseFiniteFloat(n)
300				if err != nil {
301					return p, fmt.Errorf(`field "value": %s`, err)
302				}
303				p.value = v
304			case "labels":
305				t, err := dec.Token()
306				if err != nil {
307					return p, err
308				}
309				d, ok := t.(json.Delim)
310				if !ok || d != '{' {
311					return p, fmt.Errorf(`field "labels" must be an object of string keys to string values`)
312				}
313				labels := map[string]string{}
314				for dec.More() {
315					labelKeyTok, err := dec.Token()
316					if err != nil {
317						return p, err
318					}
319					labelKey := labelKeyTok.(string)
320					if labelKey == "" {
321						return p, fmt.Errorf(`field "labels": label keys must be non-empty strings`)
322					}
323					valTok, err := dec.Token()
324					if err != nil {
325						return p, err
326					}
327					labelVal, ok := valTok.(string)
328					if !ok {
329						return p, fmt.Errorf(`field "labels": value of label %q must be a string`, labelKey)
330					}
331					if _, dup := labels[labelKey]; dup {
332						return p, fmt.Errorf(`field "labels": duplicate label key %q`, labelKey)
333					}
334					labels[labelKey] = labelVal
335				}
336				if _, err := dec.Token(); err != nil { // 消耗 '}'
337					return p, err
338				}
339				p.labels = labels
340			}
341		}
342		if _, err := dec.Token(); err != nil { // 消耗 '}'
343			return p, err
344		}
345		if _, err := dec.Token(); err != io.EOF {
346			if err == nil {
347				return p, fmt.Errorf("unexpected content after the sample object")
348			}
349			return p, err
350		}
351	
352		for _, field := range []string{"name", "timestamp", "value"} {
353			if !present[field] {
354				return p, fmt.Errorf("missing required field %q", field)
355			}
356		}
357		return p, nil
358	}
359	
360	func nextJSONNumber(dec *json.Decoder, field string) (json.Number, error) {
361		t, err := dec.Token()
362		if err != nil {
363			return "", err
364		}
365		n, ok := t.(json.Number)
366		if !ok {
367			return "", fmt.Errorf(`field %q must be a JSON number`, field)
368		}
369		return n, nil
370	}
371	
372	func parseJSONInt(n json.Number) (int64, error) {
373		s := string(n)
374		if !jsonIntegerRE.MatchString(s) {
375			return 0, fmt.Errorf("must be a JSON integer in milliseconds")
376		}
377		v, err := strconv.ParseInt(s, 10, 64)
378		if err != nil {
379			return 0, fmt.Errorf("must be within int64 range")
380		}
381		return v, nil
382	}
383	
384	func parseFiniteFloat(n json.Number) (float64, error) {
385		s := string(n)
386		if !jsonNumberRE.MatchString(s) {
387			return 0, fmt.Errorf("must be a JSON number")
388		}
389		v, err := strconv.ParseFloat(s, 64)
390		if err != nil || math.IsInf(v, 0) || math.IsNaN(v) {
391			return 0, fmt.Errorf("must be a finite number representable as float64")
392		}
393		return v, nil
394	}
395	
396	// ingestItems 完成全部采样点校验与冲突检测后再统一提交，保证整批原子性。
397	func (s *MetricStore) ingestItems(items []json.RawMessage) (*BatchResult, *LineError) {
398		type pending struct {
399			id  seriesID
400			ref SeriesRef
401			ts  int64
402			val float64
403		}
404	
405		added := 0
406		// 本批已确定身份的点（含与已写入数据重复的点），用于批内去重与冲突检测。
407		seen := make(map[seriesID]map[int64]float64)
408		// 仅记录需要落盘的新增点；校验全部通过后才提交。
409		commits := make([]pending, 0, len(items))
410	
411		failAt := func(index int, msg string) *LineError {
412			return &LineError{Status: "error", Index: index, Error: msg}
413		}
414		conflictAt := func(index int, ref SeriesRef, ts int64, existing, submitted float64) *LineError {
415			return &LineError{
416				Status: "error",
417				Index:  index,
418				Error: fmt.Sprintf("conflict: series %s at timestamp %d already has value %s, submitted %s",
419					ref, ts, formatFloat(existing), formatFloat(submitted)),
420				Conflict: &Conflict{
421					Series:    ref,
422					Timestamp: ts,
423					Existing:  existing,
424					Submitted: submitted,
425				},
426			}
427		}
428	
429		for i, item := range items {
430			pos := i + 1
431			p, err := parseSample(item)
432			if err != nil {
433				return nil, failAt(pos, err.Error())
434			}
435	
436			id := makeSeriesID(p.name, p.labels)
437			ref := SeriesRef{Name: p.name, Labels: p.labels}
438	
439			if byTS, ok := seen[id]; ok {
440				if old, ok := byTS[p.ts]; ok {
441					if old != p.value {
442						return nil, conflictAt(pos, ref, p.ts, old, p.value)
443					}
444					// 同批内重复出现且数值相同：重复，成功忽略。
445					continue
446				}
447			}
448			if sr, ok := s.series[id]; ok {
449				if old, ok := sr.points[p.ts]; ok {
450					if old != p.value {
451						return nil, conflictAt(pos, sr.ref, p.ts, old, p.value)
452					}
453					// 与此前批次已写入的值相同：重复，成功忽略。
454					if seen[id] == nil {
455						seen[id] = map[int64]float64{}
456					}
457					seen[id][p.ts] = p.value
458					continue
459				}
460			}
461	
462			added++
463			if seen[id] == nil {
464				seen[id] = map[int64]float64{}
465			}
466			seen[id][p.ts] = p.value
467			commits = append(commits, pending{id: id, ref: ref, ts: p.ts, val: p.value})
468		}
469	
470		// 全部采样点合法且无冲突，原子提交本批新增点。
471		for _, c := range commits {
472			sr := s.series[c.id]
473			if sr == nil {
474				sr = &storedSeries{ref: c.ref, points: map[int64]float64{}}
475				s.series[c.id] = sr
476			}
477			sr.points[c.ts] = c.val
478		}
479	
480		return s.snapshot(added, len(items)-added), nil
481	}
482	
483	// formatFloat 以 JSON 数值风格格式化 float64：1 与 1.0 均显示为 1。
484	func formatFloat(v float64) string {
485		return strconv.FormatFloat(v, 'g', -1, 64)
486	}
487	
488	type parsedQuery struct {
489		name   string
490		start  int64
491		end    int64
492		labels map[string]string
493	}
494	
495	// queryFromObject 严格解析查询对象并执行只读区间均值查询。
496	func (s *MetricStore) queryFromObject(raw json.RawMessage) (*QueryResult, *LineError) {
497		q, err := parseQuery(raw)
498		if err != nil {
499			return nil, &LineError{Status: "error", Error: err.Error()}
500		}
501		if q.start > q.end {
502			return nil, &LineError{Status: "error", Error: fmt.Sprintf(
503				`invalid range: "start" must not be greater than "end" (%d > %d)`, q.start, q.end)}
504		}
505		return s.runQuery(q), nil
506	}
507	
508	// parseQuery 对查询对象做严格校验：仅允许 op/name/start/end/labels，
509	// 拒绝重复键与未知字段；标量必须是精确的 JSON 类型，start/end 为 int64 毫秒。
510	func parseQuery(raw json.RawMessage) (parsedQuery, error) {
511		var q parsedQuery
512		dec := json.NewDecoder(bytes.NewReader(raw))
513		dec.UseNumber()
514	
515		tok, err := dec.Token()
516		if err != nil {
517			return q, err
518		}
519		if d, ok := tok.(json.Delim); !ok || d != '{' {
520			return q, fmt.Errorf("each query must be a JSON object")
521		}
522	
523		present := make(map[string]bool)
524		for dec.More() {
525			keyTok, err := dec.Token()
526			if err != nil {
527				return q, err
528			}
529			key := keyTok.(string)
530			switch key {
531			case "op", "name", "start", "end", "labels":
532			default:
533				return q, fmt.Errorf("unknown field %q", key)
534			}
535			if present[key] {
536				return q, fmt.Errorf("duplicate field %q", key)
537			}
538			present[key] = true
539	
540			switch key {
541			case "op":
542				t, err := dec.Token()
543				if err != nil {
544					return q, err
545				}
546				op, ok := t.(string)
547				if !ok {
548					return q, fmt.Errorf(`field "op" must be a string`)
549				}
550				if op != "query" {
551					return q, fmt.Errorf(`unknown op %q (only "query" is supported)`, op)
552				}
553			case "name":
554				t, err := dec.Token()
555				if err != nil {
556					return q, err
557				}
558				name, ok := t.(string)
559				if !ok {
560					return q, fmt.Errorf(`field "name" must be a string`)
561				}
562				if name == "" {
563					return q, fmt.Errorf(`field "name" must be a non-empty string`)
564				}
565				q.name = name
566			case "start", "end":
567				n, err := nextJSONNumber(dec, key)
568				if err != nil {
569					return q, err
570				}
571				v, err := parseJSONInt(n)
572				if err != nil {
573					return q, fmt.Errorf(`field %q: %s`, key, err)
574				}
575				if key == "start" {
576					q.start = v
577				} else {
578					q.end = v
579				}
580			case "labels":
581				t, err := dec.Token()
582				if err != nil {
583					return q, err
584				}
585				d, ok := t.(json.Delim)
586				if !ok || d != '{' {
587					return q, fmt.Errorf(`field "labels" must be an object of non-empty string keys to string values`)
588				}
589				labels := map[string]string{}
590				for dec.More() {
591					labelKeyTok, err := dec.Token()
592					if err != nil {
593						return q, err
594					}
595					labelKey := labelKeyTok.(string)
596					if labelKey == "" {
597						return q, fmt.Errorf(`field "labels": label keys must be non-empty strings`)
598					}
599					valTok, err := dec.Token()
600					if err != nil {
601						return q, err
602					}
603					labelVal, ok := valTok.(string)
604					if !ok {
605						return q, fmt.Errorf(`field "labels": value of label %q must be a string`, labelKey)
606					}
607					if _, dup := labels[labelKey]; dup {
608						return q, fmt.Errorf(`field "labels": duplicate label key %q`, labelKey)
609					}
610					labels[labelKey] = labelVal
611				}
612				if _, err := dec.Token(); err != nil { // 消耗 '}'
613					return q, err
614				}
615				q.labels = labels
616			}
617		}
618		if _, err := dec.Token(); err != nil { // 消耗 '}'
619			return q, err
620		}
621		if _, err := dec.Token(); err != io.EOF {
622			if err == nil {
623				return q, fmt.Errorf("unexpected content after the query object")
624			}
625			return q, err
626		}
627	
628		for _, field := range []string{"op", "name", "start", "end"} {
629			if !present[field] {
630				return q, fmt.Errorf("missing required field %q", field)
631			}
632		}
633		return q, nil
634	}
635	
636	// labelsMatch 实现子集匹配：want 中每个键都必须在 stored 中存在且值完全相等，
637	// stored 可以含额外标签；空字符串值只匹配真实存在的空值标签。
638	func labelsMatch(want, stored map[string]string) bool {
639		for k, v := range want {
640			got, ok := stored[k]
641			if !ok || got != v {
642				return false
643			}
644		}
645		return true
646	}
647	
648	// runQuery 只读扫描已成功提交的数据：name 精确、标签子集、[start,end] 闭区间。
649	// 结果沿用 snapshot 的序列排序；无区间内点的序列不列出。
650	func (s *MetricStore) runQuery(q parsedQuery) *QueryResult {
651		matched := make([]*storedSeries, 0)
652		for _, sr := range s.series {
653			if sr.ref.Name != q.name || !labelsMatch(q.labels, sr.ref.Labels) {
654				continue
655			}
656			has := false
657			for ts := range sr.points {
658				if ts >= q.start && ts <= q.end {
659					has = true
660					break
661				}
662			}
663			if has {
664				matched = append(matched, sr)
665			}
666		}
667		sort.Slice(matched, func(i, j int) bool {
668			if matched[i].ref.Name != matched[j].ref.Name {
669				return matched[i].ref.Name < matched[j].ref.Name
670			}
671			return compareLabelPairs(sortedPairs(matched[i].ref.Labels), sortedPairs(matched[j].ref.Labels)) < 0
672		})
673	
674		out := make([]QuerySeries, 0, len(matched))
675		for _, sr := range matched {
676			tsList := make([]int64, 0, len(sr.points))
677			for ts := range sr.points {
678				if ts >= q.start && ts <= q.end {
679					tsList = append(tsList, ts)
680				}
681			}
682			sort.Slice(tsList, func(i, j int) bool { return tsList[i] < tsList[j] })
683			values := make([]float64, len(tsList))
684			for i, ts := range tsList {
685				values[i] = sr.points[ts]
686			}
687			labels := make(map[string]string, len(sr.ref.Labels))
688			for k, v := range sr.ref.Labels {
689				labels[k] = v
690			}
691			out = append(out, QuerySeries{
692				Name:    sr.ref.Name,
693				Labels:  labels,
694				Count:   len(values),
695				Average: finiteMean(values),
696			})
697		}
698		return &QueryResult{Status: "ok", Op: "query", Series: out}
699	}
700	
701	// finiteMean 返回算术平均值，且对任意有限 float64 输入保证结果有限：
702	// 采用增量均值（Welford），当 x 与当前均值反号相减溢出时，先分别除以 n 再合并。
703	func finiteMean(values []float64) float64 {
704		mean := 0.0
705		for i, x := range values {
706			n := float64(i + 1)
707			delta := x - mean
708			if math.IsInf(delta, 0) {
709				// 溢出只可能在 n >= 2 且 x 与 mean 反号、幅值均极大时发生；
710				// 此时 |x/n|、|mean/n| 均小于 maxFloat64，差也有限，且与 mean 异号。
711				mean += x/n - mean/n
712				continue
713			}
714			mean += delta / n
715		}
716		return mean
717	}
718	
719	// String 让冲突原因中的序列身份可读：name{k=v,...}，标签按键排序。
720	func (r SeriesRef) String() string {
721		var b strings.Builder
722		b.WriteString(r.Name)
723		b.WriteByte('{')
724		for i, p := range sortedPairs(r.Labels) {
725			if i > 0 {
726				b.WriteByte(',')
727			}
728			fmt.Fprintf(&b, "%s=%s", p.Key, p.Value)
729		}
730		b.WriteByte('}')
731		return b.String()
732	}
733	
734	// snapshot 生成按规范排序的全部序列视图：先按指标名，再按标签键值对字典序，
735	// 序列内按时间戳升序。
736	func (s *MetricStore) snapshot(added, duplicates int) *BatchResult {
737		views := make([]SeriesView, 0, len(s.series))
738		for _, sr := range s.series {
739			tsList := make([]int64, 0, len(sr.points))
740			for ts := range sr.points {
741				tsList = append(tsList, ts)
742			}
743			sort.Slice(tsList, func(i, j int) bool { return tsList[i] < tsList[j] })
744			points := make([]Point, len(tsList))
745			for i, ts := range tsList {
746				points[i] = Point{Timestamp: ts, Value: sr.points[ts]}
747			}
748			labels := make(map[string]string, len(sr.ref.Labels))
749			for k, v := range sr.ref.Labels {
750				labels[k] = v
751			}
752			views = append(views, SeriesView{Name: sr.ref.Name, Labels: labels, Points: points})
753		}
754		sort.Slice(views, func(i, j int) bool {
755			if views[i].Name != views[j].Name {
756				return views[i].Name < views[j].Name
757			}
758			return compareLabelPairs(sortedPairs(views[i].Labels), sortedPairs(views[j].Labels)) < 0
759		})
760		return &BatchResult{Status: "ok", Added: added, Duplicates: duplicates, Series: views}
761	}
762

