562			`{"op":"ingest","name":"m","start":0,"end":1}`,                                      // 未知 op
563			`{"op":"write","name":"m","start":0,"end":1}`,                                       // 其他 op
564			`{"op":7,"name":"m","start":0,"end":1}`,                                             // op 类型错误
565			`{"op":"query","op":"query","name":"m","start":0,"end":1}`,                          // 重复字段
566			`{"op":"query","name":"m","start":0.5,"end":1}`,                                     // start 非整数
567			`{"op":"query","name":"m","start":"0","end":1}`,                                     // start 字符串
568			`{"op":"query","name":"m","start":true,"end":1}`,                                    // start 布尔
569			`{"op":"query","name":"m","start":0,"end":9223372036854775808}`,                     // end 超 int64
570			`{"op":"query","name":"m","start":2,"end":1}`,                                       // start > end
571			`{"op":"query","name":"m","start":-9223372036854775808,"end":-9223372036854775809}`, // end 低于 int64
572			`{"op":"query","name":"m","start":0,"end":1,"labels":[]}`,                           // labels 非对象
573			`{"op":"query","name":"m","start":0,"end":1,"labels":null}`,                         // labels 为 null
574			`{"op":"query","name":"m","start":0,"end":1,"labels":{"":"v"}}`,                     // 空标签键
