	switch sum.Sign() {
	case 0:
		return 0
	case -1:
		sum.Neg(sum)
		v := ratToFloat64(sum, new(big.Int).Lsh(big.NewInt(int64(len(values))), scaleExp))
		return -v
	}
	den := new(big.Int).Lsh(big.NewInt(int64(len(values))), scaleExp)
	return ratToFloat64(sum, den)
}
