package darksafe

import (
	"math"
	"math/big"
	"math/rand"
	"testing"
)

// 临时正确性交叉验证：finiteMean 与高精度 big.Float 参考实现比较。
func TestZZTempMeanCrossCheck(t *testing.T) {
	rng := rand.New(rand.NewSource(42))
	ref := func(vals []float64) float64 {
		// 用 4096 位精度的 big.Float 精确求和后转 float64（最近舍入）。
		sum := new(big.Float).SetPrec(4096)
		for _, v := range vals {
			sum.Add(sum, new(big.Float).SetPrec(4096).SetFloat64(v))
		}
		n := new(big.Float).SetPrec(4096).SetInt64(int64(len(vals)))
		sum.Quo(sum, n)
		out, _ := sum.Float64()
		return out
	}
	check := func(vals []float64, where string) {
		t.Helper()
		got := finiteMean(vals)
		want := ref(vals)
		if got != want || math.Signbit(got) != math.Signbit(want) {
			t.Fatalf("%s: mean=%v want %v (vals=%v)", where, got, want, vals)
		}
	}
	// 随机有限值。
	for i := 0; i < 20000; i++ {
		n := 1 + rng.Intn(8)
		vals := make([]float64, n)
		for j := range vals {
			switch rng.Intn(4) {
			case 0:
				vals[j] = math.Float64frombits(rng.Uint64()) // 任意位模式（含 Inf/NaN 概率极低）
				if math.IsInf(vals[j], 0) || math.IsNaN(vals[j]) {
					vals[j] = 1
				}
			case 1:
				vals[j] = (rng.Float64() - 0.5) * math.Pow(10, rng.Float64()*600-300)
			case 2:
				vals[j] = float64(rng.Int63n(2000)-1000) / 3.0
			default:
				vals[j] = []float64{1e16, -1e16, 1, -1, 1e308, -1e308, 1e-320, -1e-320}[rng.Intn(8)]
			}
		}
		check(vals, "random")
	}
	// 构造精确中点（tie）：两个相邻 float64 的平均。
	for i := 0; i < 20000; i++ {
		bits := rng.Uint64()
		f := math.Float64frombits(bits)
		if math.IsInf(f, 0) || math.IsNaN(f) {
			continue
		}
		next := math.Nextafter(f, math.Inf(1))
		if math.IsInf(next, 0) {
			continue
		}
		check([]float64{f, next}, "tie-2")
		check([]float64{f, next, f, next}, "tie-4")
	}
	// 极端：多个 1e308 / -1e308 与小值组合。
	for i := 0; i < 2000; i++ {
		vals := []float64{1e308, -1e308, 1e308, -1e308, 1e-320}
		rng.Shuffle(len(vals), func(a, b int) { vals[a], vals[b] = vals[b], vals[a] })
		check(vals, "extremes")
	}
}

